solution.javascript:
function potenciaMod(a, n, m) {
  let r = 1n % BigInt(m);
  let base = BigInt(a) % BigInt(m);
  let e = BigInt(n);
  const M = BigInt(m);
  while (e > 0n) {
    if (e & 1n) r = (r * base) % M;
    base = (base * base) % M;
    e >>= 1n;
  }
  return Number(r);
}

solution.python:
def potenciaMod(a, n, m):
    r = 1 % m
    base = a % m
    while n:
        if n & 1:
            r = r * base % m
        base = base * base % m
        n >>= 1
    return r
